// Call the function to retrieve a const, null-terminated identifier string.
const char *repo = mnr_repo();

// Ownership/lifetime are unspecified; do not persist or free it.
// Enforce minimal safety: if null, bail; if non-null, ensure a NUL terminator appears
// within a reasonable bound to avoid unbounded reads.
if (!repo) { FUZZ_BAIL(); }

// Bounded scan up to 2048 bytes (performance/safety constraint) for NUL terminator.
size_t max_scan = 2048;
bool has_nul = false;
for (size_t i = 0; i < max_scan; ++i) {
    if (repo[i] == '\0') { has_nul = true; break; }
}
if (!has_nul) { FUZZ_BAIL(); }

// Optional light-touch usage: read a few characters without modifying (respect constness).
volatile unsigned int checksum = 0;  // prevent optimizing away reads
for (size_t i = 0; i < 8 && repo[i] != '\0'; ++i) {
    checksum += static_cast<unsigned int>(static_cast<unsigned char>(repo[i]));
}
(void)checksum;

